Ied ied_create (Boolean pin_level , UInt16 time_0_to_1 , UInt16 time_1_to_0)
{
  Ied ied = (Ied) os_mem_request (sizeof *ied) ;

  ied->idb = idb_create (pin_level , time_0_to_1 , time_1_to_0) ;

  ied_set_level (ied , pin_level) ;

  return ied ;
}

